(function () {
  var header  = document.getElementById('vcms-header');
  var toggle  = document.getElementById('vcms-hdr-toggle');
  var closeBt = document.getElementById('vcms-hdr-close');
  var drawer  = document.getElementById('vcms-hdr-drawer');
  var overlay = document.getElementById('vcms-hdr-overlay');
  if (!header || !toggle || !drawer || !overlay) return;

  function openMenu() {
    drawer.classList.add('is-open');
    overlay.classList.add('is-open');
    toggle.classList.add('is-active');
    toggle.setAttribute('aria-expanded', 'true');
    document.documentElement.classList.add('vcms-hdr-lock');
  }
  function closeMenu() {
    drawer.classList.remove('is-open');
    overlay.classList.remove('is-open');
    toggle.classList.remove('is-active');
    toggle.setAttribute('aria-expanded', 'false');
    document.documentElement.classList.remove('vcms-hdr-lock');
  }

  toggle.addEventListener('click', function () {
    if (drawer.classList.contains('is-open')) closeMenu(); else openMenu();
  });
  if (closeBt) closeBt.addEventListener('click', closeMenu);
  overlay.addEventListener('click', closeMenu);
  Array.prototype.forEach.call(drawer.querySelectorAll('a'), function (a) {
    a.addEventListener('click', closeMenu);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') closeMenu();
  });

  function onScroll() {
    if (window.scrollY > 8) header.classList.add('is-scrolled');
    else header.classList.remove('is-scrolled');
  }
  onScroll();
  window.addEventListener('scroll', onScroll, { passive: true });

  // Ajusta automaticamente a cor do título, ícone, links e hamburguer
  // conforme o contraste com o fundo real do cabeçalho (claro ou escuro).
  function relLuminance(r, g, b) {
    var a = [r, g, b].map(function (v) {
      v /= 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2];
  }
  function parseRgb(str) {
    var m = str && str.match(/rgba?\(([^)]+)\)/);
    if (!m) return null;
    var p = m[1].split(',').map(function (v) { return parseFloat(v); });
    return { r: p[0], g: p[1], b: p[2], a: p.length > 3 ? p[3] : 1 };
  }
  function applyContrast() {
    var bg = parseRgb(window.getComputedStyle(header).backgroundColor);
    if (bg && bg.a < 0.15) {
      bg = parseRgb(window.getComputedStyle(document.body).backgroundColor);
    }
    if (!bg || isNaN(bg.r) || isNaN(bg.g) || isNaN(bg.b)) return;
    var isLight = relLuminance(bg.r, bg.g, bg.b) > 0.4;
    var root = document.documentElement;
    if (isLight) {
      root.style.setProperty('--vcms-hdr-text', 'rgba(15, 15, 20, 0.92)');
      root.style.setProperty('--vcms-hdr-text-dim', 'rgba(15, 15, 20, 0.64)');
    } else {
      root.style.setProperty('--vcms-hdr-text', 'rgba(255, 255, 255, 0.94)');
      root.style.setProperty('--vcms-hdr-text-dim', 'rgba(255, 255, 255, 0.72)');
    }
  }
  applyContrast();
  if (window.MutationObserver) {
    new MutationObserver(applyContrast).observe(header, {
      attributes: true,
      attributeFilter: ['style', 'class']
    });
  }
})();

